const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nwPennsylvania = ee.Geometry.Polygon([
    [-80.5, 41.5],
    [-79.0, 41.5], 
    [-79.0, 42.0],
    [-80.5, 42.0],
    [-80.5, 41.5]
  ]);

  const date1 = '2020-02-22';
  const date2 = '2020-03-01';

  // 2. Data Acquisition - MODIS Snow Cover Daily
  const getSnowData = function(date) {
    return ee.ImageCollection('MODIS/006/MOD10A1')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(nwPennsylvania)
      .first();
  };

  const img1 = getSnowData(date1);
  const img2 = getSnowData(date2);

  // Check if images exist
  const img1Exists = img1 ? true : false;
  const img2Exists = img2 ? true : false;

  if (!img1Exists || !img2Exists) {
    console.log(`${date1} Image: ${img1Exists ? 'Found' : 'Missing'}`);
    console.log(`${date2} Image: ${img2Exists ? 'Found' : 'Missing'}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Extract snow cover and mask poor quality
  const extractSnowCover = function(img) {
    const snowCover = img.select('NDSI_Snow_Cover');
    const quality = img.select('NDSI_Snow_Cover_Basic_QA');

    // Mask out poor quality pixels (keep only best and good quality)
    const mask = quality.lte(2); // 0=best, 1=good, 2=ok, 3=poor
    return snowCover.updateMask(mask);
  };

  const snow1 = extractSnowCover(img1);
  const snow2 = extractSnowCover(img2);

  // 4. Calculate statistics
  const calculateStats = function(snowImg, date) {
    const stats = snowImg.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: nwPennsylvania,
      scale: 1000,
      maxPixels: 1e9
    });

    const mean = stats.get('NDSI_Snow_Cover').getInfo();
    const count = stats.get('NDSI_Snow_Cover_count').getInfo();

    console.log(`${date}: Mean Snow Cover: ${mean ? mean.toFixed(2) : 'None'}, Valid Pixels: ${count}`);
    return {mean: mean, count: count};
  };

  const stats1 = calculateStats(snow1, date1);
  const stats2 = calculateStats(snow2, date2);

  // 5. Validation & Final Answer
  if (stats1.count === 0 || stats2.count === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (stats1.mean === null || stats2.mean === null || 
      isNaN(stats1.mean) || isNaN(stats2.mean)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if snow cover increased
  if (stats2.mean > stats1.mean) {
    console.log(`Snow cover increased from ${stats1.mean.toFixed(2)}% to ${stats2.mean.toFixed(2)}%`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Snow cover ${stats2.mean > stats1.mean ? 'increased' : 'decreased'} from ${stats1.mean.toFixed(2)}% to ${stats2.mean.toFixed(2)}%`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
